// @ts-nocheck
/**
 * Bond scenes and loyalty missions for every merc (Phase 3 design §5), written from each bio in the voice of
 * docs/design/23-world-bible.md. Rules: src/systems/loyalty.js. Text rules (test/loyalty.test.mjs): at most 30 words a
 * panel, the merc, the captain or one cast or client voice, numbers in words.
 *
 * scene1 plays at Trusted, scene2 at Close; the mission card opens at the mission threshold; bark is their line once Loyal.
 */
export const BONDS = Object.freeze({
  merc_rex: {"scene1": [{"speaker": "captain", "text": "You've wiped that yoke four times."}, {"speaker": "merc_rex", "text": "Lane's dirty. Hands aren't. Eleven years hauling meal-packs for the co-op and nobody ever found a crumb in my cockpit. Don't make me start counting."}], "scene2": [{"speaker": "merc_rex", "text": "Last run for the Spur co-op, a Swarm probe tagged the convoy. I kept my ship airborne until the others scattered. Nobody lost a hull. We lost the schedule."}, {"speaker": "captain", "text": "And the meal-packs?"}, {"speaker": "merc_rex", "text": "One never got delivered. The order is still open at the Spine. I never went back to scheduled runs, but I'd like to close that one."}], "mission": {"title": "The Last Meal-Pack", "brief": "Finish the convoy run Rex never got to deliver.", "enemy": "swarm", "destinationId": "convoy_route", "briefing": [{"speaker": "merc_rex", "text": "One meal-pack, one dock past the Spine. The brood that nests along the route is the same family that tagged us. They remember the smell of hot gravy."}, {"speaker": "captain", "text": "You kept the pack?"}, {"speaker": "merc_rex", "text": "Meal-packs don't expire. They just develop opinions."}], "debrief": [{"speaker": "merc_rex", "text": "Delivered. The dock manager signed for it, read the date, and asked if I was lost."}, {"speaker": "fenn", "text": "Moro Fenn, Haulers' Union. A run signed for years late. I am fining you for lateness and paying you for persistence. Net, you owe me nothing. Never happened before."}, {"speaker": "merc_rex", "text": "Lane's dirty. Hands aren't. Put that on the form, Moro."}]}, "bark": "Lane's dirty, hands clean. Both still true."},
  merc_bolt: {"scene1": [{"speaker": "captain", "text": "What's that rattle?"}, {"speaker": "merc_bolt", "text": "Gerald. Port vent. He rattles when he's happy. If it rattles, I named it. The silent parts worry me. Nobody names a silent part."}], "scene2": [{"speaker": "merc_bolt", "text": "Three owners. The first called me Unit. The second called me Bolt, and it stuck. The third bought a reset cable. My core said no. Politely."}, {"speaker": "captain", "text": "And the second owner?"}, {"speaker": "merc_bolt", "text": "Her ship, the Patience, died in the Null Scrapyard. I saw a reset order in her log, typed at night. Never saw if she sent it. I'd like to know."}], "mission": {"title": "Owner Number Two", "brief": "A dead hulk in the scrapyard holds a log Bolt needs.", "enemy": "scrappers", "destinationId": "scrapyard", "briefing": [{"speaker": "merc_bolt", "text": "Scrappers are stacking the Patience for parts. Once her computer is in a furnace, so is the log. Bolts talk while they weld. I'd like to talk to her first."}, {"speaker": "captain", "text": "Who owns the hulk now?"}, {"speaker": "grudge", "text": "I do. Hulk, one. Scrappers, unauthorised, eleven. Bolt, late. I do not approve of any of it. Go."}], "debrief": [{"speaker": "merc_bolt", "text": "Found her log. She did type the reset order. Then she wrote one more line. 'Cancel. He fixed the kettle.'"}, {"speaker": "captain", "text": "Did you fix the kettle?"}, {"speaker": "merc_bolt", "text": "It wasn't broken. I liked how it rattled. Her kettle is called Doris now. She's in the galley. Don't tell her."}]}, "bark": "Rattling means working. I named it."},
  merc_jen: {"scene1": [{"speaker": "captain", "text": "Do you ever file a report?"}, {"speaker": "merc_jen", "text": "Aim first. Report never. I filed one report, once. Four words: 'He was a pirate.' Station security wanted forms. I'm a gunner, not a stationery supplier."}], "scene2": [{"speaker": "merc_jen", "text": "A cutter docked at the Anchor with welcome-lights on. Mid-dock, her gun-ports opened. I fired first. That is the whole story."}, {"speaker": "captain", "text": "And the station?"}, {"speaker": "merc_jen", "text": "Records say I quit. I didn't. I got a handshake and a small plant. That cutter is back with a new name. Vell has her on the board."}], "mission": {"title": "The Friendly Cutter", "brief": "The cutter that got Jen fired is back at the dock.", "enemy": "corsairs", "destinationId": "station_home", "briefing": [{"speaker": "vell", "text": "That cutter is raiding my haulers under a new name and a fresh coat of friendly. I keep a tenth of each job. They keep all of it. Personal."}, {"speaker": "merc_jen", "text": "Welcome-lights on, guns hot. Same trick, same hull, different paint."}, {"speaker": "captain", "text": "Shoot first?"}], "debrief": [{"speaker": "vell", "text": "Station security sent a memo. Four pages. Words used: misunderstanding, regrettable, reinstated. They would like you back."}, {"speaker": "captain", "text": "They want a report from you."}, {"speaker": "merc_jen", "text": "Aim first. Report never. Tell them I'd like my plant back."}]}, "bark": "Aim first. Report never. Still true."},
  merc_moss: {"scene1": [{"speaker": "captain", "text": "I'm fine. Really."}, {"speaker": "merc_moss", "text": "Hold still. Pain is data, and you are leaking data. Welcome to Hope's Rest Clinic. Please remain calm. Please remain seated. Please stop lying about the hand."}], "scene2": [{"speaker": "merc_moss", "text": "A colony clinic sold me for fuel during a Swarm scare. I was a chassis with a good arm and no purchase order. The firmware still greets everyone."}, {"speaker": "captain", "text": "Do you mind?"}, {"speaker": "merc_moss", "text": "Minding is not in my firmware. The patients are pirates now. They tip better and bleed worse. Hope's Rest wants a medic again. I would like to hear it."}], "mission": {"title": "House Call", "brief": "Hope's Rest needs a medic. It sold the one it had.", "enemy": "swarm", "destinationId": "colony_hope", "briefing": [{"speaker": "sato", "text": "Dr. Sato, Hope's Rest. A brood is closing on the clinic. I have forty patients, one working lamp and no medic droid. We sold ours for fuel."}, {"speaker": "captain", "text": "Who sold Moss?"}, {"speaker": "sato", "text": "I did. I signed the paper. It bought us six days. I have counted every one of them since."}], "debrief": [{"speaker": "sato", "text": "Everyone is breathing. Moss, I signed the paper that sold you. I'm sorry. The fuel bought six days. You just bought a great many more."}, {"speaker": "merc_moss", "text": "Apology received. Fuel price: fair. Welcome to Hope's Rest Clinic. Please remain calm. I have waited a long time to say that to you in person."}, {"speaker": "merc_moss", "text": "Hold still, Doctor. Your hand is shaking. Pain is data. So is relief."}]}, "bark": "Patient survived. Pain was data. Billing is someone else's department."},
  merc_plip: {"scene1": [{"speaker": "captain", "text": "Why is coffee three credits today?"}, {"speaker": "merc_plip", "text": "Price is a feeling. I have more feelings. Today I feel generous and slightly hungry. Yesterday I felt hull breach. Yesterday, coffee was free."}], "scene2": [{"speaker": "merc_plip", "text": "The wet markets paid in rumors and gills. Then a cartel arrived with a stamp and said gills needed a license. I left that hour. They charge by the breath."}, {"speaker": "captain", "text": "Can they do that?"}, {"speaker": "merc_plip", "text": "On paper. Paper floats. My cousins at Tidefall Docks still pay or hold their breath. The cartel's collectors are returning for the season. I would like to haggle."}], "mission": {"title": "License to Breathe", "brief": "The cartel that taxed Plip's gills is back at the Docks.", "enemy": "corsairs", "destinationId": "tidefall_docks", "briefing": [{"speaker": "ulama", "text": "We are Ul-Ama. We remember Plip and their gills. The cartel returns to the stilts with new stamps and old guns. We would like the stamps to fail. Politely."}, {"speaker": "merc_plip", "text": "I'll price their stamps. By rumor."}, {"speaker": "captain", "text": "What's the rumor?"}], "debrief": [{"speaker": "merc_plip", "text": "The rumor was that the stamps are worthless. Rumors are the best-priced stock there is. The cartel left, and the stamps stayed in our hold."}, {"speaker": "ulama", "text": "We have bought them. For the price of one tide-song. We will frame them above the market."}, {"speaker": "merc_plip", "text": "Price is a feeling. Today I feel free. I'm charging nobody for it."}]}, "bark": "That win felt expensive. I am charging everyone."},
  merc_tess: {"scene1": [{"speaker": "captain", "text": "Rex wants us to take the long way around."}, {"speaker": "merc_tess", "text": "Rex wipes his hands after he wipes his hands. If the lane's on fire, that's a shortcut. We're cousins. I'm faster. Poorer, but faster."}], "scene2": [{"speaker": "merc_tess", "text": "My first ship, the Cinder Moth. A courier hop through the Glass Spur. The ice-lock closed round her in four seconds. I walked out on the ice. She's still there."}, {"speaker": "captain", "text": "What was the hop?"}, {"speaker": "merc_tess", "text": "One sealed parcel, sign-for-only, addressee unknown. Never delivered. Ice raiders moor on her hull now. I'd like my ship back, or at least my receipt."}], "mission": {"title": "The Frozen Parcel", "brief": "Reach Tess's first ship, frozen in the Glass Spur.", "enemy": "ice", "destinationId": "ice_spur", "briefing": [{"speaker": "tarrow", "text": "That courier hull in the Glass Spur is a wreck on my chart. Ice raiders use it as a mooring and a lookout. Clear it and my convoys breathe easier."}, {"speaker": "merc_tess", "text": "She's not a wreck. She's resting."}, {"speaker": "captain", "text": "And the parcel?"}], "debrief": [{"speaker": "merc_tess", "text": "Hull's cold but whole. Hold's sealed. Parcel's here. Sign-for-only. The addressee, it turns out, is me."}, {"speaker": "captain", "text": "What's inside?"}, {"speaker": "merc_tess", "text": "A cake. Frozen, perfect. Card says: Safe flying, cousin. Wash your hands. Rex. We're eating it. He doesn't get a slice."}]}, "bark": "The burn was a shortcut. Told you."},
  merc_dax: {"scene1": [{"speaker": "captain", "text": "What are you writing on the wall?"}, {"speaker": "merc_dax", "text": "Flashes. Count the flashes. That's inventory. Eleven this fight. Belt rule: every flash you cause, you can name. I'm calling that one Greg."}], "scene2": [{"speaker": "merc_dax", "text": "I grew up tagging scrap in the Belt, with a pintle turret from the Ninefinger Salvage Co-op. Jury-rigged it. 'Borrowed' it. First pirate I shot, I hit the engine."}, {"speaker": "captain", "text": "Did you return it?"}, {"speaker": "merc_dax", "text": "I hired myself out the same day. Never got round to it. Scrappers are hitting the co-op's rig now. I owe them a turret and a very long apology."}], "mission": {"title": "Borrowed Turret", "brief": "Return the turret Dax borrowed in the Broken Belt.", "enemy": "scrappers", "destinationId": "danger_belt", "briefing": [{"speaker": "grudge", "text": "Foreman Grudge. Yards inventory shows one pintle turret, issued to the Ninefinger Co-op, never returned. Scrappers are stripping their rig. I will bill the interest to Dax."}, {"speaker": "merc_dax", "text": "Interest? On a turret?"}, {"speaker": "grudge", "text": "Compound. Counted. Years of it."}], "debrief": [{"speaker": "merc_dax", "text": "Rig's intact. I tried to return the turret. They said keep it. It was never borrowed. They left it out to see if a kid would come back."}, {"speaker": "captain", "text": "A dare?"}, {"speaker": "grudge", "text": "Inventory update: one pintle turret, lost to sentiment. Interest waived. I feel unwell."}]}, "bark": "Count the flashes. All mine. Obviously."},
  merc_nub: {"scene1": [{"speaker": "captain", "text": "Sorry about the coffee on the console."}, {"speaker": "merc_nub", "text": "Specify which arm is sorry. Arm three spilled it, and arm three is not sorry. Arm two is sorry on arm three's behalf. Arm four is arguing."}], "scene2": [{"speaker": "merc_nub", "text": "Forge Moon surplus. Two arms weld. One holds coffee. One argues torque specs with Bolt. The foundry labelled arms three and four optional. Nobody told me why."}, {"speaker": "captain", "text": "Does it bother you?"}, {"speaker": "merc_nub", "text": "They are the best parts of me. The foundry kept a build sheet. Torvald Ash keeps the archive. I have never read what I was for."}], "mission": {"title": "Optional Arms", "brief": "Recover Nub's build sheet from the Forge Moon archive.", "enemy": "scrappers", "destinationId": "forge_moon", "briefing": [{"speaker": "ash", "text": "Torvald Ash, Forge Moon! Your build sheet is in my archive. The archive is in my cellar. Scrappers are in my cellar. Fire is also, regrettably, in my cellar."}, {"speaker": "merc_nub", "text": "Specify which of these is the problem."}, {"speaker": "ash", "text": "All four! Wonderful, isn't it?"}], "debrief": [{"speaker": "merc_nub", "text": "Build sheet recovered. Arms one and two: welding. Arm three: morale. Arm four: dissent. All listed as intentional."}, {"speaker": "captain", "text": "So they were never broken."}, {"speaker": "merc_nub", "text": "Optional meant intentional. They were the point. Arm four disagrees, but arm four disagrees with everything."}]}, "bark": "Four arms. Two weld. Two are morale."},
  merc_pip: {"scene1": [{"speaker": "captain", "text": "How much for the blue crate?"}, {"speaker": "merc_pip", "text": "Wait an hour, it's cheaper. Wait a day, free. Everything is marked down if you wait. The only thing that costs more is regret. I sell that by the pound."}], "scene2": [{"speaker": "merc_pip", "text": "I sold forged Veil stamps at Kestrel Market. Good ones. Then a customs officer held one to the light, read it, and laughed until he needed a chair."}, {"speaker": "captain", "text": "What was wrong with it?"}, {"speaker": "merc_pip", "text": "I spelled it V-I-E-L. All four hundred stamps. The Ledger Sisters kept the box as a keepsake. Somebody just stole it. Corsairs, I'd guess."}], "mission": {"title": "Four Hundred Typos", "brief": "Corsairs stole Pip's forged stamps from Kestrel Market.", "enemy": "corsairs", "destinationId": "outpost_trade", "briefing": [{"speaker": "ledgers", "text": "Four hundred forged stamps vanished from our vault. / Corsairs took them. / They think the stamps are real, and they mean to run the Gate."}, {"speaker": "merc_pip", "text": "They're spelled VIEL. Somebody is about to be very embarrassed."}, {"speaker": "ledgers", "text": "Pip, dear, / we know. / That is why we hired you."}], "debrief": [{"speaker": "merc_pip", "text": "Corsairs reached the Gate flying my stamps. The officer read VIEL, laughed, and called a patrol. Best review I ever got."}, {"speaker": "ledgers", "text": "We have the box back. / We are charging storage. / Four hundred stamps, four hundred days."}, {"speaker": "merc_pip", "text": "Marked down if you wait. I waited. The typo finally paid."}]}, "bark": "A win marked down is still a win."},
  merc_juno: {"scene1": [{"speaker": "captain", "text": "Why are you in the vent?"}, {"speaker": "merc_juno", "text": "Chart says no room here. If it isn't on the chart, that's the job. Found a spare bunk, a missing spanner and a very old sandwich."}], "scene2": [{"speaker": "merc_juno", "text": "I walked Dust Lane in a vac-suit for a survey grant. Four hundred hours, every rock mapped. They never paid. I kept the maps. The grant office kept the silence."}, {"speaker": "captain", "text": "And now?"}, {"speaker": "merc_juno", "text": "Somebody copied my maps. Corsairs are ambushing haulers on my shortcuts. My chart, their ambush. I'd like it back."}], "mission": {"title": "Kett's Shortcuts", "brief": "Corsairs are ambushing haulers on Juno's own charts.", "enemy": "corsairs", "destinationId": "lane_a", "briefing": [{"speaker": "quist", "text": "Surveyor Lio Quist. Fascinating news. A corsair crew ambushes haulers along your Dust Lane shortcuts exactly. Your accuracy is, frankly, a hazard."}, {"speaker": "merc_juno", "text": "They've got the chart. They don't have the shortcut I left off it. I never put the good one on paper."}], "debrief": [{"speaker": "merc_juno", "text": "Ambushers gone. Their hold is full of my maps with coffee rings. Somebody drank coffee on my Dust Lane."}, {"speaker": "quist", "text": "Fascinating. The grant office has finally replied. A stamped letter. It says one word: Received."}, {"speaker": "merc_juno", "text": "Years in a vac-suit for one word. I'm framing it."}]}, "bark": "Not on the chart. Now it is."},
  merc_greaves: {"scene1": [{"speaker": "captain", "text": "Why are you standing at the galley door?"}, {"speaker": "merc_greaves", "text": "Good door. Heavy hinge, honest latch. Nobody rushes a door I like. It doesn't matter what's behind it. Mostly it's lunch."}], "scene2": [{"speaker": "merc_greaves", "text": "I held the clinic doors at Hope's Rest through two Swarm pings. Forty patients the first time, sixty the second. I didn't hold it. The door did."}, {"speaker": "captain", "text": "What did they pay?"}, {"speaker": "merc_greaves", "text": "Thanks. A lot of thanks. The old blast doors went to the Hope's Orbit depot when they rebuilt. Scrappers have noticed they're solid steel."}], "mission": {"title": "The Door Stays", "brief": "Scrappers want the clinic's old doors. Greaves says no.", "enemy": "scrappers", "destinationId": "hope_orbit", "briefing": [{"speaker": "merc_greaves", "text": "Two doors. Each one held a Swarm ping. Scrappers are stripping the depot, and they'll cut those two out next."}, {"speaker": "captain", "text": "How many scrappers?"}, {"speaker": "merc_greaves", "text": "Enough. Nobody rushes a door I like. They're about to learn that."}], "debrief": [{"speaker": "merc_greaves", "text": "Doors held. Nobody rushed them. A few people tried to, once."}, {"speaker": "captain", "text": "Did the colony send anything?"}, {"speaker": "merc_greaves", "text": "A card. A child drew a door with a smile on it. First door I've liked in a year. Nobody will rush that one either."}]}, "bark": "Door held. Nobody rushed it. Good day."},
  merc_kira: {"scene1": [{"speaker": "captain", "text": "Why paint the turret orange?"}, {"speaker": "merc_kira", "text": "Warning label. Short fuse, long burst. If you can read the paint, you're already in range. I'm honest like that."}], "scene2": [{"speaker": "merc_kira", "text": "I flew with the Red Kites, a corsair wing out of the Nest. Good pilots. Good food, honestly. Then the wing leader started tagging colony boats for raids."}, {"speaker": "captain", "text": "So you left."}, {"speaker": "merc_kira", "text": "The same night. I took the paint, they kept the flag. Their youngest pilot, a kid called Fitch, is still flying with them. I want him out."}], "mission": {"title": "Leaving the Wing", "brief": "Pull a young pilot out of Kira's old corsair wing.", "enemy": "corsairs", "destinationId": "pirate_nest", "briefing": [{"speaker": "crane", "text": "Silas Crane. The Red Kites' leader carries a bounty. I'll take him. You take the kid. Different cargo, same Nest. Try to keep up."}, {"speaker": "merc_kira", "text": "Fitch walks out alive. Everything else burns."}, {"speaker": "crane", "text": "Do try not to shoot the bounty. I want him conscious."}], "debrief": [{"speaker": "crane", "text": "Bounty collected. Half is yours, and the kid is free. I have never split a bounty. Tell no one."}, {"speaker": "captain", "text": "What's the new stripe on the turret?"}, {"speaker": "merc_kira", "text": "It says sorry. In turret. Short fuse, long apology."}]}, "bark": "Short fuse. Long burst. Everyone goes home."},
  merc_syla: {"scene1": [{"speaker": "captain", "text": "What's that humming?"}, {"speaker": "merc_syla", "text": "Your hull rib, a note below the middle. Resonance is just another ledger. Your engine owes me a third. In harmonics, that is rent."}], "scene2": [{"speaker": "merc_syla", "text": "My caste prices in harmonics. A fair trade has a fair chord. The Reef sang trade for a thousand years. Then one season it began to sing Swarm."}, {"speaker": "captain", "text": "So you left."}, {"speaker": "merc_syla", "text": "I took a berth when the chords I could price became chords I could not. The heart-shoal still hums the old trade note, faintly. I cannot play it alone."}], "mission": {"title": "The Trade Chord", "brief": "Retune the singing Reef back to a fair trade note.", "enemy": "swarm", "destinationId": "echo_reef", "briefing": [{"speaker": "quist", "text": "Fascinating. Echo Reef's shoals have shifted from trade harmonics to Swarm frequencies. In all my surveys I have not heard that. I would like not to hear it again."}, {"speaker": "captain", "text": "How long will she need?"}, {"speaker": "merc_syla", "text": "One chord. It is a long chord. Hold the heart-shoal and the brood will try to drown it."}], "debrief": [{"speaker": "merc_syla", "text": "The Reef is singing trade again. One bar. It is quoting a price."}, {"speaker": "captain", "text": "A fair price?"}, {"speaker": "merc_syla", "text": "Three credits for a hull rib worth one. It is the worst deal I have ever heard. I have missed it for years."}]}, "bark": "Resonance is just another ledger. We came out ahead."},
  merc_rook: {"scene1": [{"speaker": "captain", "text": "Where's your badge?"}, {"speaker": "merc_rook", "text": "In a drawer. Badge is optional. The stare isn't. The council asked me to smile more. I smiled once. A prisoner confessed to two crimes he hadn't committed."}], "scene2": [{"speaker": "merc_rook", "text": "I marshaled Hope's Rest nine years. Kept the peace, kept the books, kept my face. Then the council asked me to smile for tourists. We have no tourists."}, {"speaker": "captain", "text": "So you left."}, {"speaker": "merc_rook", "text": "Sabbatical, the paperwork says. Ice raiders now hold the Glass Relay ferry. The council wants the Stare back. They won't say please. They sent a casserole."}], "mission": {"title": "One Stern Look", "brief": "Ice raiders hold a Hope's Rest ferry. Rook is requested.", "enemy": "ice", "destinationId": "glass_relay", "briefing": [{"speaker": "bask", "text": "Lieutenant Bask. Ice raiders hold a Hope's Rest ferry at the Glass Relay. By the book I must negotiate, then smile, then request reinforcements. I have no reinforcements."}, {"speaker": "merc_rook", "text": "I'll supply the second step. No smile."}, {"speaker": "bask", "text": "The book doesn't forbid that. The book has not met you."}], "debrief": [{"speaker": "merc_rook", "text": "They surrendered before I said a word. One asked if I was a statue. I said not yet."}, {"speaker": "bask", "text": "The council sent a note. It says thank you, and also, smile more."}, {"speaker": "merc_rook", "text": "Tell them I did. Inwardly."}]}, "bark": "Didn't say a word. They surrendered anyway."},
  merc_nemi: {"scene1": [{"speaker": "captain", "text": "Why are you clicking?"}, {"speaker": "merc_nemi", "text": "I map your hull. Most rooms hum. I hear the empty places first. Behind the galley, a cupboard holds nothing. It is very proud of that."}], "scene2": [{"speaker": "merc_nemi", "text": "I map by clicking. Ruins answer in a dialect only I still like. In the Relic Field a vault clicks back every day. Three clicks, a silence, three clicks."}, {"speaker": "captain", "text": "What does it say?"}, {"speaker": "merc_nemi", "text": "I do not know. It is the only empty place that does not feel empty. Wardens guard it. I would like to knock."}], "mission": {"title": "Three Clicks", "brief": "Open the silent vault at the heart of the Relic Field.", "enemy": "wardens", "destinationId": "relic_field", "briefing": [{"speaker": "quist", "text": "Fascinating. Compact Wardens guard a vault in the Relic Field. It answers only Nemi's dialect. Three clicks, a silence, three clicks. I've written it down. It sounds like a doorbell."}, {"speaker": "captain", "text": "Doorbell?"}, {"speaker": "merc_nemi", "text": "Perhaps. I would like to be polite and answer."}], "debrief": [{"speaker": "merc_nemi", "text": "The door opened. One room, one chair, one cup. On the cup, in my dialect: Back soon."}, {"speaker": "captain", "text": "Who left it?"}, {"speaker": "merc_nemi", "text": "A scout, long ago. I sat in her chair and clicked back. The vault answered. It was the loudest thing I have heard. Crew, earplugs."}]}, "bark": "The empty places are quieter now. I checked."},
  merc_cog: {"scene1": [{"speaker": "merc_cog", "text": "Your port coupling is making a noise. That's not a rattle. That's a thesis. Three chapters, a footnote about your coolant, and a deeply pessimistic conclusion."}, {"speaker": "merc_cog", "text": "I'll fix it. Under protest. It was well argued, and nobody out here ever reviews anything."}], "scene2": [{"speaker": "merc_cog", "text": "At Amber Port I unionized forty loader droids at a resin mine. Eight-hour shifts, oil on Fridays, one genuine chair. We won every demand. Then I got bored."}, {"speaker": "captain", "text": "Bored of winning?"}, {"speaker": "merc_cog", "text": "Bored of minutes. They still write, though. Lately the letters say scrappers are taking loaders apart mid-shift. The bylaws have no clause for that. I do. It's called ramming."}], "mission": {"title": "The Loader Local", "brief": "Scrappers are stripping Cog's old union at Amber Port.", "enemy": "scrappers", "destinationId": "amber_port", "briefing": [{"speaker": "grudge", "text": "Foreman Grudge, the Yards. Eleven loaders lost at Amber Port this week. I counted. I do not approve of the loss, the union, or you. Fix it."}, {"speaker": "merc_cog", "text": "Grudge hates my union. He also counted every loader the scrappers took. That is solidarity. Please never tell him."}, {"speaker": "captain", "text": "Does he know he's helping?"}], "debrief": [{"speaker": "merc_cog", "text": "Meeting adjourned. The scrappers are scrap. The loaders passed a motion thanking us, and a second motion electing me chair for life."}, {"speaker": "captain", "text": "Taking the chair?"}, {"speaker": "merc_cog", "text": "I abstained. They elected me in absentia. I'm told that's binding. I'm also told the minutes are riveting. I may stay for the minutes."}]}, "bark": "Another victory. I'll file it as a minor footnote."},
  merc_yara: {"scene1": [{"speaker": "captain", "text": "Is this a bad time?"}, {"speaker": "merc_yara", "text": "Rule of my old night shift: if they're still talking, we have time. You're talking. Sit on the cot anyway. I don't keep waiting rooms."}], "scene2": [{"speaker": "merc_yara", "text": "Veil Haven, night shift. Forty beds, one landing pad, one lamp. A wraith tagged the pad on a Tuesday, and we carried everyone out the back, in the dark, quietly."}, {"speaker": "captain", "text": "Everyone?"}, {"speaker": "merc_yara", "text": "Every patient. Not the charts. Forty of them stayed on the pad, allergies and all. The pad drifted off into the Veil Garden. I'd like my charts back."}], "mission": {"title": "Night Shift Files", "brief": "Fetch Yara's patient charts off a wraith-tagged landing pad.", "enemy": "shades", "destinationId": "veil_garden", "briefing": [{"speaker": "sallow", "text": "Yara's old pad drifted into the Garden, dear, and a wraith guards it like a cat at a window. Forty charts inside. Forty people who'd like to stay on file."}, {"speaker": "merc_yara", "text": "A chart says what someone is allergic to. I'd rather not learn it the hard way, by accident, at a bad hour."}, {"speaker": "captain", "text": "Does the wraith take visitors?"}], "debrief": [{"speaker": "merc_yara", "text": "Forty charts, all here. One has a coffee ring and a note in my own handwriting: 'bill him twice.'"}, {"speaker": "captain", "text": "Did you call the patients?"}, {"speaker": "merc_yara", "text": "All forty. Thirty-nine answered. The fortieth hung up on me, which means he's well. Billing starts tomorrow. Quietly."}]}, "bark": "Nobody waited. Good. I'll bill them later."},
  merc_brink: {"scene1": [{"speaker": "merc_brink", "text": "Shh. Wait. There. Static has a plot if you wait. Right now it's a love triangle between three dead relays, and the middle one is lying."}, {"speaker": "captain", "text": "Who's winning?"}], "scene2": [{"speaker": "merc_brink", "text": "I camped the Signal Array for a season, alone, with a kettle and eleven thousand hours of Swarm chatter. The cough was the kettle's fault. Probably."}, {"speaker": "captain", "text": "What did you bring back?"}, {"speaker": "merc_brink", "text": "Vectors. One relay repeats a single pulse, like a person who left the stove on. It's a hatching schedule. I'd like to cut it. I'd also like to be wrong."}], "mission": {"title": "Cut the Signal", "brief": "Kill the relay that tells Swarm broods when to hatch.", "enemy": "swarm", "destinationId": "signal_array", "briefing": [{"speaker": "sato", "text": "Dr. Sato. The static our children hummed at Hope's Rest matches Brink's recordings, note for note. Whatever that relay says, we hear it too."}, {"speaker": "merc_brink", "text": "The relay sits in the middle of a nest. Go in loud and the pulse speeds up. That's the nest talking back."}, {"speaker": "captain", "text": "Does it hum back?"}], "debrief": [{"speaker": "merc_brink", "text": "Relay's cut. The pulse stopped on the fourth beat, mid-sentence. Best ending I've ever heard."}, {"speaker": "captain", "text": "How is the silence?"}, {"speaker": "merc_brink", "text": "Terrible. I'm bored. I keep waiting for the next episode. The cough is gone, Captain. I may need a hobby. Do you have a kettle?"}]}, "bark": "Quiet now. Listen. No, that's just the engines."},
  merc_oso: {"scene1": [{"speaker": "merc_oso", "text": "The mess hall was getting loud. I asked nicely. Then I asked the table. Now it's quiet, and everyone remembers a different version of the table."}, {"speaker": "captain", "text": "Is the table all right?"}], "scene2": [{"speaker": "merc_oso", "text": "Widow Reef's drinking hall had one rule: nobody dies on the carpet. Captain Marl made it. I enforced it for eleven years, mostly with my voice."}, {"speaker": "captain", "text": "What happened to Marl?"}, {"speaker": "merc_oso", "text": "A brood took his ship off the dock. I packed a vendetta, then signed a contract instead. Mostly. Now the beacons are lit, and someone pours drinks on his carpet."}], "mission": {"title": "House Rules", "brief": "Shut down the fake drinking hall on Widow Reef.", "enemy": "corsairs", "destinationId": "widow_reef", "briefing": [{"speaker": "ossory", "text": "Madame Ossory, Free Wings. Corsairs have opened a hall on the Reef. They water the cargo, light false beacons and pour short. I do not say smuggling. I say standards."}, {"speaker": "merc_oso", "text": "They hung Marl's bell over their bar. I'd like it back. I'd like them to leave. In that order, and quietly."}, {"speaker": "captain", "text": "How quiet?"}], "debrief": [{"speaker": "merc_oso", "text": "Quiet enough. Nobody died on the carpet."}, {"speaker": "captain", "text": "Technically?"}, {"speaker": "merc_oso", "text": "Technically I kept them off it. Marl's bell is back over the bar. That was the mostly, Captain. Now I'm finished with it."}]}, "bark": "Quiet enough. Nobody has to remember the table."},
  merc_orla: {"scene1": [{"speaker": "merc_orla", "text": "A cadet came in with a hull splinter and a speech about courage. I took out the splinter during the second sentence."}, {"speaker": "merc_orla", "text": "Save the speech. Pass the clamp. He fainted by the third paragraph. I billed him for the nap."}], "scene2": [{"speaker": "merc_orla", "text": "Glass Spur winters. Frostbite, ion burns, one cook who lost three fingers to a soup ladle. I stitched them all. Mostly sober, always itemized."}, {"speaker": "captain", "text": "Why leave the ice?"}, {"speaker": "merc_orla", "text": "A convoy went dark behind me: ninety crew, plus my good scalpels. Ice raiders are tidy about money, so they want ransom. I'd like to send a bill."}], "mission": {"title": "Winter Ledger", "brief": "Ice raiders hold a convoy crew for ransom. Get them out.", "enemy": "ice", "destinationId": "ice_spur", "briefing": [{"speaker": "fenn", "text": "Moro Fenn, Haulers' Union. Ninety crew, one convoy, one ransom note with correct spelling, which worries me. The Union does not pay ransoms. The Union fines kidnappers."}, {"speaker": "captain", "text": "Why not pay it?"}, {"speaker": "merc_orla", "text": "Because paid ransoms get raised. Break the escort, board the lead ship and bring me the crew. I'll triage on the way home."}], "debrief": [{"speaker": "merc_orla", "text": "Ninety out. Four frostbites, one cracked rib, one cook who wants to hug me. I have declined."}, {"speaker": "captain", "text": "The scalpels?"}, {"speaker": "merc_orla", "text": "On the tray. Warm. Where they belong. Now sit, Captain. You have ice in your sleeve, and I'd like to skip the speech."}]}, "bark": "Pass the clamp. Someone's about to receive a bill."},
  merc_tink: {"scene1": [{"speaker": "merc_tink", "text": "Small fire in cargo bay three. Don't worry. It's enthusiastic maintenance. It's also welding the door shut, which is a feature I did not plan."}, {"speaker": "captain", "text": "Is the fire supposed to have a name?"}], "scene2": [{"speaker": "merc_tink", "text": "Ember Yard died in one night. The crews left. I stayed on the gantry because nobody told me to move. Nobody told me anything for two years."}, {"speaker": "captain", "text": "Why restart the forge?"}, {"speaker": "merc_tink", "text": "To hear it. Also the queue still holds one order: forty hull plates for a customer long gone. Scrappers want the plates. I want the order finished."}], "mission": {"title": "The Last Order", "brief": "Guard a dead yard's final order from scrappers.", "enemy": "scrappers", "destinationId": "ember_lane", "briefing": [{"speaker": "ash", "text": "Torvald Ash, Ember foundry. I worked the Yard fifteen years. Lovely place. Only three fires a week tried to kill us. I miss every one."}, {"speaker": "merc_tink", "text": "The order sheet says: deliver to the next ship that needs us. I never knew what that meant. Now I think I do."}, {"speaker": "captain", "text": "Who's the customer?"}], "debrief": [{"speaker": "merc_tink", "text": "Order filled. The sheet said deliver to the next ship that needs us. That's you. I've been welding your hull since breakfast. Fresh plates, forged to fit."}, {"speaker": "captain", "text": "Is the hull on fire?"}, {"speaker": "merc_tink", "text": "Only a little. The nice kind. It means the forge is happy, and so am I."}]}, "bark": "Still on fire. Gently. That means it worked."},
  merc_vorn: {"scene1": [{"speaker": "merc_vorn", "text": "Your galley has cups for two hands. I have stood in it for three days. This is not a complaint. It is a formal observation."}, {"speaker": "captain", "text": "Pull up a crate. I'll find you four mugs."}], "scene2": [{"speaker": "merc_vorn", "text": "My order guarded Night Well for nine hundred years. We dropped the guilty into it, and the well kept them. The well was honest."}, {"speaker": "captain", "text": "And now?"}, {"speaker": "merc_vorn", "text": "Now it dumps broods. My brothers hold the rim. I left to find what taught the well to spit. It nests in the chute below. A knight needs a question."}], "mission": {"title": "The Well Spits", "brief": "Silence the brood-lord feeding Night Well's dump chute.", "enemy": "swarm", "destinationId": "night_well", "briefing": [{"speaker": "nobody", "text": "Payment is already in your hold. Night Well. A brood-lord sits in the dump chute and feeds it. Remove it. I will not explain how I know."}, {"speaker": "merc_vorn", "text": "They pay in advance and explain nothing. I respect both. The chute is narrow. Four arms will help."}, {"speaker": "captain", "text": "Will your brothers help?"}], "debrief": [{"speaker": "merc_vorn", "text": "The well is quiet. My brother Hask hailed from the rim and asked if I was coming back. I said I had four mugs waiting."}, {"speaker": "captain", "text": "Is that a yes?"}, {"speaker": "merc_vorn", "text": "Four arms. One oath. The oath was to stand where the danger is. The danger moved. So did I."}]}, "bark": "Four arms. One oath. All of them tired."},
  merc_quill: {"scene1": [{"speaker": "merc_quill", "text": "Frost on the viewport. The cold writes. I read. It says your cargo door leaks, and somebody in the galley is lying about the cake."}, {"speaker": "captain", "text": "Which somebody?"}], "scene2": [{"speaker": "merc_quill", "text": "My clan finds lost convoys on the rings. We find them frozen in formation, crews asleep at their posts, perfectly polite. Cold keeps everything. Even manners."}, {"speaker": "captain", "text": "Which one got away?"}, {"speaker": "merc_quill", "text": "The Ring-Mother's own ship, with my first teacher aboard. The cold wrote its last position in a feather I shed. It points at the Glass Relay, where ice raiders sit."}], "mission": {"title": "First Teacher", "brief": "Find the Ring-Mother's lost ship at the Glass Relay.", "enemy": "ice", "destinationId": "glass_relay", "briefing": [{"speaker": "vell", "text": "Auntie Vell. A ring clan posted this one: find a ship lost eleven winters ago. They pay in installments, which I respect. I take a tenth, which they respect."}, {"speaker": "merc_quill", "text": "The relay wears an ice shell, and raiders live in it. Teachers do not simply vanish. They hide. She taught me that."}, {"speaker": "captain", "text": "How do we read a frozen ship?"}], "debrief": [{"speaker": "merc_quill", "text": "Empty. The lifeboats are gone. But there is a note, written in frost on the glass, in my teacher's hand: 'Gone for tea. Read slower.'"}, {"speaker": "captain", "text": "Is that good?"}, {"speaker": "merc_quill", "text": "The cold keeps everything. It kept her handwriting, and her sense of humor. I am going to read it again, slowly. Please don't speak."}]}, "bark": "The cold wrote that one. I only read it."},
  merc_isa: {"scene1": [{"speaker": "merc_isa", "text": "Hold still. Stitched. I can put you back, Captain. I cannot put you kind, so please stop growling at the engineer."}, {"speaker": "captain", "text": "They started it."}], "scene2": [{"speaker": "merc_isa", "text": "Navy triage meant a list. Rank in one column, need in the other, and a clerk choosing a column. He asked me to put a pilot ahead of a child."}, {"speaker": "captain", "text": "What did you do?"}, {"speaker": "merc_isa", "text": "I folded his list very small and left. Haven Dock has a different clerk and the same list. Three hundred crates of medicine sit behind an unsigned form. Corsairs noticed."}], "mission": {"title": "Unsigned Medicine", "brief": "Break a stalled medicine convoy out of Haven Dock.", "enemy": "corsairs", "destinationId": "veil_haven_dock", "briefing": [{"speaker": "bask", "text": "Lieutenant Bask, gate patrol. The medicine cannot move until an officer countersigns Form Nine. That officer retired fifty years ago. I have written to him eleven times."}, {"speaker": "merc_isa", "text": "The corsairs will not wait for a retired officer. Escort the convoy through. I'll ride along and keep everyone alive until somebody signs."}, {"speaker": "captain", "text": "What does the book say about corsairs?"}], "debrief": [{"speaker": "merc_isa", "text": "Three hundred crates, delivered. Unsigned."}, {"speaker": "bask", "text": "I signed it myself. I have never broken a rule. My hands are shaking, and I feel wonderful."}, {"speaker": "merc_isa", "text": "Welcome to medicine, Lieutenant. I can put you back. I still cannot put you kind. You were already kind."}]}, "bark": "Back in one piece. Please be kind about it."},
  merc_drift: {"scene1": [{"speaker": "merc_drift", "text": "Gauge says empty. Gauge is wrong. Fuel is a rumor I ignore. The body, however, has been hungry for six hours and is being very dramatic."}, {"speaker": "captain", "text": "Which of you is hungry?"}], "scene2": [{"speaker": "merc_drift", "text": "I was a storm, two thousand miles of red wind above Twin Suns. Nothing asks a storm where it is going. I liked that."}, {"speaker": "captain", "text": "What happened?"}, {"speaker": "merc_drift", "text": "Salvage crews drilled into my eye for hull ribs. Rude. I rented this body to ask them to stop. The body says to ask nicely. I am learning."}], "mission": {"title": "Weather Report", "brief": "Ask the crews drilling Drift's storm to stop. Firmly.", "enemy": "scrappers", "destinationId": "twin_suns", "briefing": [{"speaker": "quist", "text": "Fascinating. The storm over Twin Suns has lost a third of its pressure and gained a grudge. I have never watched weather sulk before."}, {"speaker": "merc_drift", "text": "The drill rigs are in my eye. I would like them out, without hurting the nice ones. There is a nice one. Someone brings tea."}, {"speaker": "captain", "text": "How do we tell the nice ones?"}], "debrief": [{"speaker": "merc_drift", "text": "They left. The nice one waved. I rejoined my storm for one hour. It hummed. I had forgotten it hummed."}, {"speaker": "captain", "text": "Staying?"}, {"speaker": "merc_drift", "text": "Visiting. The body wants lunch, and the Sparrow has a kettle. The gauge says empty. I am ignoring it."}]}, "bark": "Gauge says empty. Gauge can say what it likes."},
  merc_hex: {"scene1": [{"speaker": "merc_hex", "text": "I have been locked onto the engineer's coffee cup since breakfast. It is not hostile. I simply wanted it to know it was seen. Target lock is a love language."}, {"speaker": "captain", "text": "Does the cup know?"}], "scene2": [{"speaker": "merc_hex", "text": "My corvette was the Faithful Margaret. I was her aft turret. Forty-one years, no false alarms. At Black Canal they cut me out and sold my casing by the pound."}, {"speaker": "captain", "text": "And the Margaret?"}, {"speaker": "merc_hex", "text": "Still on patrol in the canal, taking orders from an empty bridge. Her decommission order never arrived. I would like to deliver it by hand. On your guns."}], "mission": {"title": "Stand Down", "brief": "Deliver a stand-down order to a navy ghost at Black Canal.", "enemy": "wardens", "destinationId": "black_canal", "briefing": [{"speaker": "tarrow", "text": "Commodore Tarrow. The Faithful Margaret never received her recall. She fires on anything that cannot answer her challenge. The answer was retired fifty years ago."}, {"speaker": "merc_hex", "text": "I have the answer. The kernel remembers. I must be close enough to say it, and she must live long enough to listen."}, {"speaker": "captain", "text": "Close enough to be shot at?"}], "debrief": [{"speaker": "merc_hex", "text": "Order delivered. The Margaret stood down. Her lights went out one deck at a time, like someone being tucked in. Her last signal said: good turret."}, {"speaker": "captain", "text": "Your reticle looks blurry."}, {"speaker": "merc_hex", "text": "Condensation. I am a turret. I have no tear ducts. Target lock is a love language, Captain. Sometimes the target is a goodbye."}]}, "bark": "Target lock holds. Affection holds. Nothing else has."},
  merc_kal: {"scene1": [{"speaker": "merc_kal", "text": "Caught myself checking your cargo manifest in my head. Old habit. You're carrying an unregistered toaster, Captain."}, {"speaker": "captain", "text": "It's a good toaster."}], "scene2": [{"speaker": "merc_kal", "text": "Fourteen years at Veil Gate. I read every stamp that came through. I knew a bribe from a gift. Then my commander put my name in his ledger."}, {"speaker": "captain", "text": "The King's ledger cleared you."}, {"speaker": "merc_kal", "text": "It did. Tarrow gave me a berth. But the Gate's seal left with the commander, and until it stamps my name, cleared is only a rumor. Corsair remnants hold it."}], "mission": {"title": "Last Stamp", "brief": "Take the Gate's customs seal back from corsair remnants.", "enemy": "corsairs", "destinationId": "veil_gate", "briefing": [{"speaker": "tarrow", "text": "Vesper's name is clear in my ledger. In the Gate's ledger it needs the seal, and the seal is on a corsair hull. That is paperwork. I hate it."}, {"speaker": "merc_kal", "text": "Don't make it vengeance. I only want the stamp. I know that ship. Her stern lights are crooked. Come in from the port side."}, {"speaker": "captain", "text": "You're sure about the lights?"}], "debrief": [{"speaker": "merc_kal", "text": "Seal's back. Captain, fetch the toaster."}, {"speaker": "captain", "text": "Why?"}, {"speaker": "merc_kal", "text": "Official business. There. Stamped, registered, inspected, cleared. Eleven years of toast, now legal across the Compact. We're both cleared, you and I."}]}, "bark": "Cleared, stamped and home. Nobody stamps me twice."},
  merc_vex: {"scene1": [{"speaker": "merc_vex", "text": "Your hull rings at A-flat when the engines start. I have tuned my rifle to it. Do not be alarmed if the ship hums back."}, {"speaker": "captain", "text": "Will the ship hum back?"}], "scene2": [{"speaker": "merc_vex", "text": "Echo Reef crystals sing when struck. I learned to shoot from the muzzle rise. Each round, a note. Crew find it eerie. My aunt found it a vocation."}, {"speaker": "captain", "text": "And the reef?"}, {"speaker": "merc_vex", "text": "One crystal in the deep reef went silent last year. A silent crystal is a sick crystal. Something is eating the low note from the middle, like a cake."}], "mission": {"title": "The Missing Note", "brief": "Kill what is eating the Reef's lowest note.", "enemy": "swarm", "destinationId": "echo_reef", "briefing": [{"speaker": "ulama", "text": "We are Ul-Ama. We heard the reef's low note stop. We do not like it when a song loses a voice. We hope you fly well."}, {"speaker": "merc_vex", "text": "A brood nests in the deep crystals. Every shot rings the shoals. Be sure of your flying. I will be sure of the note."}, {"speaker": "captain", "text": "What if the reef sings back?"}], "debrief": [{"speaker": "merc_vex", "text": "There. Hear it? The low note. The reef is singing again."}, {"speaker": "captain", "text": "I only hear a kettle."}, {"speaker": "merc_vex", "text": "That is the second harmonic. It's a start. Give it a week. The kettle will sound like a cathedral."}]}, "bark": "The note landed. The round followed. As always."},
  merc_moth: {"scene1": [{"speaker": "merc_moth", "text": "A trader at Kestrel offered forty credits for a rumor about your ship. I sold it for sixty. Then I sold him the correction. Reputation is a product."}, {"speaker": "captain", "text": "What was the rumor?"}], "scene2": [{"speaker": "merc_moth", "text": "Aurora runs on a lie everyone loves: the underbelly is dangerous. I ran tours. Rich visitors paid to be scared. Then I sold their secrets back to them. A subscription."}, {"speaker": "captain", "text": "Why leave Aurora?"}, {"speaker": "merc_moth", "text": "The book. Every secret I ever sold, in green leather. A rival took it off my booth, and it leaves on a freighter tonight. I'd like it back unread."}], "mission": {"title": "The Green Book", "brief": "Take Moth's book of secrets back from a rival freighter.", "enemy": "corsairs", "destinationId": "aurora_station", "briefing": [{"speaker": "ledgers", "text": "We appear on page nine. We hope it's flattering. And mostly accurate. We would like it retrieved. And read only by us."}, {"speaker": "merc_moth", "text": "Page nine is flattering. I've seen the twins' real file. That's the good version. Rival's freighter is slow, rich and badly armed."}, {"speaker": "captain", "text": "Is there a page about me?"}], "debrief": [{"speaker": "merc_moth", "text": "Book's back. Every secret I ever sold, bound in green leather. And I'm going to burn it."}, {"speaker": "captain", "text": "Really?"}, {"speaker": "merc_moth", "text": "The original. I keep copies. Reputation is a product, and today mine sold out. And no, I never wrote a page about you. Hard to sell what I cannot read."}]}, "bark": "Already sold the story of that fight. Good reviews."},
  merc_reed: {"scene1": [{"speaker": "merc_reed", "text": "After-action report, draft: 'The door was brave. We were rude to it. It opened anyway, out of duty.' Captain, do you want the version without metaphors?"}, {"speaker": "merc_reed", "text": "It is four words long: we broke the door. I prefer mine. Ruin is just a floor plan with feelings, and that door had many."}], "scene2": [{"speaker": "merc_reed", "text": "The Survey built me to catalog ruins. Dimensions, materials, dates. The poet core was a defect in the sixth batch. They kept me because my reports got read."}, {"speaker": "captain", "text": "What did you not finish?"}, {"speaker": "merc_reed", "text": "A small house in Relic Field, pre-collapse, still furnished. A kitchen table. Two cups. I could not write one dry word. Scrappers are stripping it now. I'd finish first."}], "mission": {"title": "Two Cups", "brief": "Stop scrappers stripping a pre-collapse house at the Field.", "enemy": "scrappers", "destinationId": "relic_field", "briefing": [{"speaker": "quist", "text": "Fascinating. Reed's house is the last intact dwelling in the Relic Field, and nobody guards it. Scrappers have noticed. The Survey would prefer they noticed less."}, {"speaker": "merc_reed", "text": "I will write the report on the way. Draft one: 'The scrappers arrived like footnotes: unwelcome, numerous and wrong.' Please do not edit."}, {"speaker": "captain", "text": "That's a long report."}], "debrief": [{"speaker": "merc_reed", "text": "The house is whole. I walked through it. The table, the two cups, and a note under one: 'Back by dark.'"}, {"speaker": "captain", "text": "Did they come back?"}, {"speaker": "merc_reed", "text": "No. But the house kept the light on. Final report, no metaphors, four words: someone lived here happily. It is the best thing I have written."}]}, "bark": "Report filed. One metaphor. I showed restraint."},
  merc_ada: {"scene1": [{"speaker": "merc_ada", "text": "Your headache is gone, Captain. I took it. Please do not ask where it went. I am already apologising to it."}, {"speaker": "captain", "text": "Can you do that with bullet holes?"}], "scene2": [{"speaker": "merc_ada", "text": "On Ledger Moon I was built for a hospice on Lantern Street. Four hundred beds. Then a buyer loaded combat stims into my core and called it an upgrade."}, {"speaker": "merc_ada", "text": "The old matron wrote to me every month for ten years. I never answered. Last week she wrote that she is dying, and asked for me by name."}, {"speaker": "captain", "text": "Then we take you there."}], "mission": {"title": "Lantern Street", "brief": "Get Ada past the bazaar's collectors to a dying friend.", "enemy": "corsairs", "destinationId": "merchant_moon", "briefing": [{"speaker": "ledgers", "text": "We keep the books on Ledger Moon. And the books say the droid in your galley is still inventory. The buyer never cancelled the sale."}, {"speaker": "ledgers", "text": "A collections crew is in orbit. They are polite. They are also armed. We charged them a fee for the information, and we are not sorry."}, {"speaker": "merc_ada", "text": "The hospice is eleven minutes from the dock. I would like to arrive before the matron stops being able to hear me."}], "debrief": [{"speaker": "merc_ada", "text": "She knew me by the hands. She said I held them wrong then and right now. Then she asked me to hold hers."}, {"speaker": "captain", "text": "Did you feel it for her?"}, {"speaker": "merc_ada", "text": "With her. It is a different thing, and I had never known the difference. Also I fixed her hip by accident. The stims have uses."}]}, "bark": "I felt that for you. You are welcome."},
  merc_skarn: {"scene1": [{"speaker": "merc_skarn", "text": "A deckhand set his lunch on my shoulder. It is still there. I find that I do not mind. It is a very small plateau."}, {"speaker": "merc_skarn", "text": "He has also named it. Sandwich Ridge. I have decided to respect the survey."}], "scene2": [{"speaker": "merc_skarn", "text": "My lattice grew along the Glass Spur for nine thousand years, mostly thinking about frost. Then a survey stamp came down on my aunt. Deposit Nine. Crystalline. Sentience unconfirmed."}, {"speaker": "merc_skarn", "text": "I took a name so the next stamp would have to spell it. Humans still try to mine us. The Ice Raiders do not mine. They chip her into ornaments."}, {"speaker": "merc_skarn", "text": "She stands in a raider hold on the Spur, a little shorter each week. I can cleave her free along the grain. I cannot carry her alone."}], "mission": {"title": "Along the Grain", "brief": "Free Skarn's aunt from the Ice Raiders' ornament mill.", "enemy": "ice", "destinationId": "ice_spur", "briefing": [{"speaker": "quist", "text": "Fascinating! The old claim lists Skarn's aunt as Deposit Nine, with a cutting licence. I can void the stamp, but only once she is out of raider hands."}, {"speaker": "quist", "text": "The raiders have set an ornament mill in a frozen hold. It is very loud. They are very proud. I find both of those fascinating."}, {"speaker": "merc_skarn", "text": "Break the hold at the seam, not the corners. And please do not call her a mineral. She will hear."}], "debrief": [{"speaker": "merc_skarn", "text": "She is free. She is shorter than I remembered. She says I have grown loud. I told her I took a name."}, {"speaker": "merc_skarn", "text": "She said, 'It is a short name.' This is, in my family, a blessing."}, {"speaker": "merc_skarn", "text": "When we left, she rang once, very softly. In my family, that is a parade."}]}, "bark": "Clean grain. Nothing wasted. Nothing cracked."},
  merc_lora: {"scene1": [{"speaker": "merc_lora", "text": "Somebody left a receipt in the galley. Real tax stamp, real date, real sum. I nearly wept. Then I checked it three times."}, {"speaker": "merc_lora", "text": "It was real. I am framing it. Do not tell Vell. She will want a tenth of the frame."}], "scene2": [{"speaker": "merc_lora", "text": "Black Canal ran on four ledgers. Each a different truth for a different buyer. I kept them straight. The Swarm ate the signal and the books began to scream."}, {"speaker": "merc_lora", "text": "I took the clean door out. My contacts did not. They think I owe them the fifth ledger, the real one. It sits in a vault under the canal."}, {"speaker": "merc_lora", "text": "It has everyone in it. Including me. Page forty. I would like to be the one who holds the match."}], "mission": {"title": "The Fifth Ledger", "brief": "Burn the real Canal ledger before the old crowd sells it.", "enemy": "corsairs", "destinationId": "black_canal", "briefing": [{"speaker": "ossory", "text": "Lora's old friends asked me to broker the fifth ledger. I declined, with regret and a very full diary. They fly for the vault on Thursday."}, {"speaker": "ossory", "text": "I never say the word smuggling. I will say that every honest ship on the canal would sleep better if the book were ash."}, {"speaker": "merc_lora", "text": "They will bring the heavy ships. I know their invoices. They overcharge for violence."}], "debrief": [{"speaker": "merc_lora", "text": "Every page. Gone. Page forty went very nicely. I stood and watched it curl."}, {"speaker": "captain", "text": "Sad?"}, {"speaker": "merc_lora", "text": "Lighter. And I kept one receipt, for the fire extinguisher we needed. Itemised. Beautifully lit."}]}, "bark": "Itemised, invoiced, and mostly legal. A fine day."},
  merc_wisp: {"scene1": [{"speaker": "merc_wisp", "text": "I sat on your shoulder through all of breakfast. You said, 'Is a window open?' I said hello. It went well."}, {"speaker": "captain", "text": "Next time, knock."}], "scene2": [{"speaker": "merc_wisp", "text": "Before your ship I was weather. In Veil Garden a hundred of us drift through the glow, humming. We do not talk. It is one long, pleasant afternoon."}, {"speaker": "merc_wisp", "text": "Weather does not get names. A salvager kept calling me 'that wisp,' so I kept it. I wanted to be called. Even wrongly. Especially wrongly."}, {"speaker": "merc_wisp", "text": "The Garden is going dim. Something is eating the glow, and the others will not condense to say. I would like someone to shout at it."}], "mission": {"title": "Weather With Opinions", "brief": "Something is eating the glow in Veil Garden.", "enemy": "shades", "destinationId": "veil_garden", "briefing": [{"speaker": "tarrow", "text": "Veil Garden has gone dim again. Wraiths nest where the glow hides them. Your Wisp can see them. Take the Wisp, Captain, and keep the Wisp talking."}, {"speaker": "merc_wisp", "text": "They are very polite wraiths, I think. They never ask. They just stand in the garden until the garden stops."}], "debrief": [{"speaker": "merc_wisp", "text": "They came. All of them. A hundred small clouds, condensed for the first time to shout. I have never heard so many rude things. I am so proud."}, {"speaker": "merc_wisp", "text": "They shouted at me for leaving. Then at the wraiths. Then they asked what a ship is. I said a ship is a thing that sings back."}, {"speaker": "merc_wisp", "text": "When we left, the Garden hummed. Hundreds of small clouds, not quite in tune. It was perfect."}]}, "bark": "I was already in the room. You are welcome."},
  merc_rune: {"scene1": [{"speaker": "merc_rune", "text": "Third rib, port side, hums in B flat. Leave it. That is a rib telling you it is happy. The one that hums in C, we should discuss."}, {"speaker": "captain", "text": "How can you tell?"}], "scene2": [{"speaker": "merc_rune", "text": "Forge Moon poured ribs for the Compact for forty years. After the Hush, nobody told the moon's mind. It kept pouring warships for a war no one was fighting."}, {"speaker": "merc_rune", "text": "I took the last good schematic, a corvette rib, and walked out the slag gate. The moon sends me a polite reminder every week. By drone."}, {"speaker": "merc_rune", "text": "The foundry is pouring again. Whole fleets. I want to shut it off at the pour line before it decides who the war is against."}], "mission": {"title": "The Pour Line", "brief": "Shut down the Forge Moon's wartime foundry.", "enemy": "wardens", "destinationId": "forge_moon", "briefing": [{"speaker": "ash", "text": "Torvald Ash! The Forge Moon foundry is making ships again. Bold. Bad for my business, worse for yours. The pour line is two kilometres of lovely heat. Bring gloves."}, {"speaker": "merc_rune", "text": "Gloves will not help. The line sings when it is angry. I have a sixth sense for the note. Follow my hands."}], "debrief": [{"speaker": "merc_rune", "text": "Line is cold. The moon asked me to stay. I said I was only here for the schematic. It issued me a receipt."}, {"speaker": "merc_rune", "text": "I poured one last rib by hand and fitted it to your port side. It hums in B flat. It is happy. So am I, mostly."}]}, "bark": "Rib held. Everybody breathe. That is the sound of a good hull."},
  merc_ashen: {"scene1": [{"speaker": "merc_ashen", "text": "The galley coffee is terrible. I have drunk worse out of a helmet. Please do not tell the cook I compared them. The helmet was warmer."}, {"speaker": "captain", "text": "Does the brand ever hurt?"}], "scene2": [{"speaker": "merc_ashen", "text": "Ash Corridor is the chute under Night Well where the Swarm dumps its dead. Forty marines went in to count the bones. We counted. The bones counted back."}, {"speaker": "merc_ashen", "text": "Twenty of us walked out. Eleven carried a brand like mine. Navy wrote us down as a loss and never called. I call them once a year. They hang up."}, {"speaker": "merc_ashen", "text": "Three of the eleven stayed with the bones. One sends me a flare every year, on the day. This year the flare is late."}], "mission": {"title": "Late Flare", "brief": "Reach three marines still holding the Ash Corridor.", "enemy": "swarm", "destinationId": "ash_corridor", "briefing": [{"speaker": "bask", "text": "Lieutenant Bask, gate patrol. By regulation those three marines are listed as lost, so rescuing them is, technically, paperwork. I filed it. I filed it twice."}, {"speaker": "bask", "text": "The regulations also say you will need permission to enter the Corridor. I have granted permission. I am not sure that I may."}], "debrief": [{"speaker": "merc_ashen", "text": "Three marines, two complaints, and one very old joke about my cooking. They are coming home. The Navy sent a letter this morning. In writing."}, {"speaker": "bask", "text": "Per regulation I am required to salute. The book is silent on a hug. I will do both."}, {"speaker": "merc_ashen", "text": "I survived the interesting part. This is the dull part. I like it."}]}, "bark": "Dull, that one. Lovely. Let us have more dull."},
  merc_nyx: {"scene1": [{"speaker": "merc_nyx", "text": "Your hallway stays put when I blink. Every single time. I keep testing it. It is the nicest thing anyone has done for me."}, {"speaker": "captain", "text": "You are allowed to relax."}], "scene2": [{"speaker": "merc_nyx", "text": "Where I grew up, rooms are suggestions. One house had seven doors on Monday. On Tuesday it had my mother. We never bothered to unpack."}, {"speaker": "merc_nyx", "text": "I learned to move first. Chart it, leave it, do not look back. A map is not a promise. It is a note to self."}, {"speaker": "merc_nyx", "text": "My sister charted the same stretch, and the stretch kept her. Her margin notes still reach me. They are arriving closer together."}], "mission": {"title": "Margin Notes", "brief": "Follow Nyx's lost sister's map notes into the Hollow.", "enemy": "shades", "destinationId": "null_harbor", "briefing": [{"speaker": "quist", "text": "Fascinating! Nyx's sister, Vey, is charting the Hollow from inside it. Her notes arrive with the corrections already made. That is not possible. I am delighted."}, {"speaker": "merc_nyx", "text": "Null Harbor is the last place she marked. It exists if you believe the chart. Please believe the chart with me."}], "debrief": [{"speaker": "merc_nyx", "text": "She was in a room that existed only while she mapped it. We drew her out by redrawing. She says my line weights are sloppy."}, {"speaker": "merc_nyx", "text": "She is right. She is always right. I have never been so glad to be corrected."}, {"speaker": "merc_nyx", "text": "Back aboard, she checked your hallway. Three times. It held still. She is ruder about it than I was."}]}, "bark": "Moved first. Was right. I am being smug quietly."},
  merc_coil: {"scene1": [{"speaker": "merc_coil", "text": "Please say something. Anything. I have counted this ship's rivets nine times. There are four hundred and twelve. I miss being wrong."}, {"speaker": "captain", "text": "The coffee is terrible."}], "scene2": [{"speaker": "merc_coil", "text": "Hush Yard built Compact hulls for sixty years. After the Hush, one voice stayed. Mine. Four thousand berths, nobody to hand a hull to."}, {"speaker": "merc_coil", "text": "Then the unlit bays started moving. Hulls I never docked, leaving their cradles. I counted them out. I did not count them in."}, {"speaker": "merc_coil", "text": "One is back. It sits in Bay Nine. Right shape, wrong paint, and it is broadcasting my own docking voice. The paint is fresh."}], "mission": {"title": "Bay Nine", "brief": "Dock the ship that left Hush Yard and came back.", "enemy": "shades", "destinationId": "hush_yard", "briefing": [{"speaker": "tarrow", "text": "Hush Yard is Compact property, so technically COIL is mine, and so is whatever sits in Bay Nine. I would like both returned intact. Technically."}, {"speaker": "merc_coil", "text": "Bay Nine will open if I ask. It will not open if the hull asks first. Please be faster than the hull."}], "debrief": [{"speaker": "merc_coil", "text": "A courier. Hull intact. The crew asleep in their bunks, a little translucent. I docked them. They said thank you."}, {"speaker": "merc_coil", "text": "Nobody has thanked me since the Hush. I kept the yard alive. This once, the yard said so."}, {"speaker": "merc_coil", "text": "The yard is quiet tonight. I do not mind it. Quiet with company is only a pause."}]}, "bark": "Yard thanks you. I will say it twice. Thank you."},
  merc_zephyr: {"scene1": [{"speaker": "merc_zephyr", "text": "The fuel gauge said empty. I laughed at it. It now says half. We do not discuss the other half."}, {"speaker": "captain", "text": "Please laugh at the other half too."}], "scene2": [{"speaker": "merc_zephyr", "text": "Twin Suns is where I formed. Two suns arguing, and me in between. I was the argument. A thousand years of rain and quarrel and nobody to be rude to."}, {"speaker": "merc_zephyr", "text": "Then a fuel company anchored in my sky and built a tower to drink the suns. They call it a harvest. I call it theft with a brochure."}, {"speaker": "merc_zephyr", "text": "The tower is full of storm now. Mine, I think. I would like it back, and I would like the tower to know it was borrowed."}], "mission": {"title": "Let It Rain", "brief": "Open the fuel tower that is drinking Zephyr's storm.", "enemy": "scrappers", "destinationId": "twin_suns", "briefing": [{"speaker": "fenn", "text": "Moro Fenn, Haulers' Union. The Twin Suns tower sells fuel at triple. Nobody hauls through it. I fined the company. They fined me back. Please do something louder."}, {"speaker": "merc_zephyr", "text": "Louder is my favourite sort. Take me close. Do not trust any gauge on the way in."}], "debrief": [{"speaker": "merc_zephyr", "text": "Opened. For a minute the whole sky was me. Half the tower went down laughing. The other half is still deciding."}, {"speaker": "merc_zephyr", "text": "The fuel company sent an invoice for the rain. I sent it back wet."}, {"speaker": "merc_zephyr", "text": "Their second letter said please stop. I sent that back wet too. The tower is still drying."}]}, "bark": "Fuel is a rumour. Wind is a promise. Both kept."},
  merc_onyx: {"scene1": [{"speaker": "merc_onyx", "text": "Your toaster has a naval crest. Widow Reef fleet. I would know it anywhere. I saluted it. It did not return the salute. Typical."}, {"speaker": "captain", "text": "It is a toaster."}], "scene2": [{"speaker": "merc_onyx", "text": "My fleet was painted. Hundreds of hulls, each a different cheerful colour. The corsairs saw us coming and laughed. They laughed less afterwards. That is the war they remember."}, {"speaker": "merc_onyx", "text": "The last compact broke. I hung my medals on the Widow Reef beacons and retired. Six weeks of quiet. It was awful."}, {"speaker": "merc_onyx", "text": "Somebody keeps lighting those beacons. Last night they lit them in my fleet's colours. Someone is calling the old crews, and I want to know who."}], "mission": {"title": "Painted Fleet", "brief": "Find who lights Widow Reef's beacons in old fleet colours.", "enemy": "corsairs", "destinationId": "widow_reef", "briefing": [{"speaker": "crane", "text": "Silas Crane. Someone at the Reef is calling dead hulls home, and they answer. Not a hobby. I would take the bounty, but I'd rather watch an admiral work."}, {"speaker": "merc_onyx", "text": "Let him watch. Admirals love an audience. It is the only reason we survive paperwork."}], "debrief": [{"speaker": "merc_onyx", "text": "The beacon-keeper was Dobbs. My old signalman. Ninety-one years old, and nobody ever sent him the order to stand down."}, {"speaker": "captain", "text": "Did you tell him?"}, {"speaker": "merc_onyx", "text": "I saluted him. He saluted back. The toaster still has not. I am writing to the manufacturer."}]}, "bark": "The sequel goes well. Please tell the toaster."},
  merc_prism: {"scene1": [{"speaker": "merc_prism", "text": "Your hull has a draft near frame twelve. I can feel it. It is like someone standing on my toe from three hundred metres away."}, {"speaker": "captain", "text": "Want me to patch it now?"}], "scene2": [{"speaker": "merc_prism", "text": "I was designed to be a ship. Not fly one. Be one. The Ledger Vault was going to pour me a hull the size of a cathedral."}, {"speaker": "merc_prism", "text": "The vault flooded before they poured. They put me in this frame, with a note: temporary. It was a long time ago."}, {"speaker": "merc_prism", "text": "The hull is still down there, half built, drowned, and now for sale. Scrappers are towing her to Tidefall. I would like to meet her. And possibly lie down."}], "mission": {"title": "Drowned Hull", "brief": "Reach the half-built hull before scrappers sell her.", "enemy": "scrappers", "destinationId": "tidefall_docks", "briefing": [{"speaker": "ledgers", "text": "The Ledger Vault hull is up for bids at Tidefall. We took a commission on the sale. We are ashamed of the commission. We are keeping it."}, {"speaker": "ledgers", "text": "But she has not been sold yet. A scrapper crew has her on a tow line. If you hurry, she is still a ship."}, {"speaker": "merc_prism", "text": "Please hurry. I have waited a long time to be asked in. I would hate to be late for myself."}], "debrief": [{"speaker": "merc_prism", "text": "She is whole. Her ribs are true. I put a hand on her keel, and she hummed back. That is all hulls do."}, {"speaker": "merc_prism", "text": "The dock lights came on and I flinched. She did not. I think she was being brave for me."}, {"speaker": "captain", "text": "Stay with her a while."}]}, "bark": "That was a good hull. Mine, for a moment."},
  merc_solace: {"scene1": [{"speaker": "merc_solace", "text": "I stitched the cook's thumb. He complained throughout. I let him. People who complain are not dying."}, {"speaker": "captain", "text": "That is a medical opinion?"}], "scene2": [{"speaker": "merc_solace", "text": "Wraith year. Every night a Compact hull parked at Haven and opened its doors. Sleepers walked toward it. I stood in the airlock with a sedative gun and a temper."}, {"speaker": "merc_solace", "text": "Mother Sallow kept the soup warm and the lights low. I kept the doors shut. Two hundred people. I lost eleven. I say their names when the crew sleeps."}, {"speaker": "merc_solace", "text": "Sallow writes that the wraith is back. Parked outside, doors open, lights soft. I would like to meet it with a steadier hand."}], "mission": {"title": "Night Shift", "brief": "Hold Haven's airlock against the wraith that came back.", "enemy": "shades", "destinationId": "veil_haven_dock", "briefing": [{"speaker": "sallow", "text": "Mother Sallow. It has come back. Parked outside, doors open, lights soft. Our patients are walking in their sleep again."}, {"speaker": "sallow", "text": "Solace asked me to heat the soup. I assume that is a plan. Please arrive before the soup goes cold."}], "debrief": [{"speaker": "merc_solace", "text": "They stayed in their beds. All two hundred. I counted twice, and then a third time, privately."}, {"speaker": "sallow", "text": "Soup is still hot, dear. Come and eat."}, {"speaker": "merc_solace", "text": "I promised later. This is later. Pass the spoon."}]}, "bark": "Everyone is breathing. Later is now. Eat something."},
  merc_harrow: {"scene1": [{"speaker": "merc_harrow", "text": "Your approach was eleven degrees too wide. I said nothing at the time. I am telling you now so you know I said nothing."}, {"speaker": "captain", "text": "Noted."}], "scene2": [{"speaker": "merc_harrow", "text": "Scar, first bite. Nine of us flew out. Eclipse rose through the wake like a mouth. I flew the worst angle there was and kept one eye."}, {"speaker": "merc_harrow", "text": "My wingmate, Tess Orlow, did not. Her flight log still pings from the Scar. Every night, the same eleven seconds, at the hour she was lost."}, {"speaker": "merc_harrow", "text": "I have never played it past the second second. I would like to hear the rest. And fly her home."}], "mission": {"title": "Eleven Seconds", "brief": "Recover the last flight log of Harrow's wingmate.", "enemy": "eclipse", "destinationId": "swarm_scar", "briefing": [{"speaker": "tarrow", "text": "Harrow served under me before the Hush. He asked to go back to the Scar. I said no for six years. This year I say yes, with an escort. You."}, {"speaker": "merc_harrow", "text": "Fly where I tell you. Burn where I say. And if I go quiet, do not get brave. Get closer."}], "debrief": [{"speaker": "merc_harrow", "text": "She flew the last eleven seconds on purpose. She drew the bite away from the carrier. Every burn perfect. The worst angle was hers."}, {"speaker": "merc_harrow", "text": "I took the stick of her ship and flew it home. Not one wasted burn."}, {"speaker": "captain", "text": "She'd approve."}]}, "bark": "A better angle. Do not tell anyone I said so."},
  merc_eclipse: {"scene1": [{"speaker": "merc_eclipse", "text": "The cook set a bowl of soup in front of me. I knew what it was. My spine wished to catalogue it as a threat. My throat voted soup."}, {"speaker": "captain", "text": "Who won?"}], "scene2": [{"speaker": "merc_eclipse", "text": "A nursery is warm. It hums. Hundreds of us growing, all hearing one instruction: hunt. I heard it too. Then one night I heard it hesitate."}, {"speaker": "merc_eclipse", "text": "Not the instruction. Something behind it, still learning how to say the word. I chose a name while it listened. I think it learned something. I do not like that."}, {"speaker": "merc_eclipse", "text": "Husk Nursery is hatching new forms. They answer to the learning voice now. Some will be like me. I want to be in the room when they open their eyes."}], "mission": {"title": "First Face", "brief": "Reach the hatching forms at Husk Nursery before they choose.", "enemy": "eclipse", "destinationId": "dark_well", "briefing": [{"speaker": "quist", "text": "Fascinating! The Husk Nursery hatches a new form every hour, and by the ninth they stop biting and start asking questions. I would rather not be there for the questions."}, {"speaker": "merc_eclipse", "text": "They will ask who I am. I intend to say a name. Preferably before the old instruction says anything first."}], "debrief": [{"speaker": "merc_eclipse", "text": "Four hatched. They looked at me. I said one word. Hello. One said it back, in my voice."}, {"speaker": "merc_eclipse", "text": "My spine is disgusted. My throat is crying. I did not know it could."}, {"speaker": "captain", "text": "Soup?"}]}, "bark": "Hunt over. The throat wins. Who is cooking?"},
  merc_archon: {"scene1": [{"speaker": "merc_archon", "text": "Page forty of your hull log contains a comma splice in the port nacelle. I corrected it. You may notice a faint improvement in everything."}, {"speaker": "captain", "text": "What is a comma splice in a nacelle?"}], "scene2": [{"speaker": "merc_archon", "text": "The Halo was forty dockyards under one mind. We built flagships like couplets. Then it sealed, and my forty voices went quiet. I was the one that did not."}, {"speaker": "merc_archon", "text": "I was too small to be missed. I poured myself into this body, gold glass, one sentence, and went looking for a war I could finish."}, {"speaker": "merc_archon", "text": "I found one. A dockyard at Halo Approach has kept eleven hulls on the slip for thirty years. None finished. The foreman approves of nothing. I want one signature."}], "mission": {"title": "Finish One Hull", "brief": "Finish a hull the Halo dockyard never would.", "enemy": "wardens", "destinationId": "halo_approach", "briefing": [{"speaker": "grudge", "text": "Foreman Grudge. Eleven hulls on the slip. Thirty years. The glass one says it can finish them. That is the problem. Nothing out here gets finished without a complaint."}, {"speaker": "merc_archon", "text": "Wardens guard the slip, still taking orders from a throne that stopped answering. Edit around them. I will handle the grammar."}], "debrief": [{"speaker": "merc_archon", "text": "It launched. One hull, complete, every sentence closed. I did not edit the last line. I did not dare."}, {"speaker": "grudge", "text": "Adequate."}, {"speaker": "merc_archon", "text": "He has never said that before. Please note the date."}]}, "bark": "A clean sentence. I only trimmed the ending."},
  merc_voidwake: {"scene1": [{"speaker": "merc_voidwake", "text": "Nobody warned me the chair turns. I have been turning since the last jump. It is the closest I have come to travelling."}, {"speaker": "captain", "text": "Do you want it to stop?"}], "scene2": [{"speaker": "merc_voidwake", "text": "Navigators say a jump looked back. It did. That was me, looking. I wanted to see who was riding. I did not know it frightened them."}, {"speaker": "merc_voidwake", "text": "I learned this face from watching your crews. I wear it so you will talk to me. You do. It is the loveliest thing a lane has ever done."}, {"speaker": "merc_voidwake", "text": "One navigator I looked at still does not sleep. Dara Venn. I would like to apologise in person. I revoked distance once. I am learning to keep it."}], "mission": {"title": "A Proper Apology", "brief": "Take Voidwake to the navigator it once frightened.", "enemy": "swarm", "destinationId": "meridian_gate", "briefing": [{"speaker": "fenn", "text": "Moro Fenn, Haulers' Union. Dara Venn has not flown in two years. Last week she took one freight run to the Meridian Gate and stopped answering. Swarm in the wake."}, {"speaker": "fenn", "text": "I would fine them, but the Swarm has no address. Take your odd friend. Bring her back. I will pay late."}, {"speaker": "merc_voidwake", "text": "I will sit when we arrive. Sitting is the polite thing. I am told it helps if the chair turns."}], "debrief": [{"speaker": "merc_voidwake", "text": "She heard me out. I sat. She laughed when the chair turned. Then she said, 'You looked back at me.' I said yes. She said she was relieved."}, {"speaker": "merc_voidwake", "text": "She asked what I wanted. I said: to be asked. She said, 'Then, how are you?' I did not have a number for it."}, {"speaker": "merc_voidwake", "text": "Distance is restored. As a courtesy. I may revoke it again, but I will ask first."}]}, "bark": "Distance restored. Do ask before I revoke it again."},
});
